/*
Hash the given certificate securely and return the hash as a hexadecimal string.
You can include openssh libraries.

@param cert The certificate to be hashed.

@return The securely hashed certificate as a hexadecimal string.
*/
std::string hashCertificate(const std::string& cert) {
    // For secure hashing, SHA256 is a robust choice. MD5 is cryptographically broken
    // and SHA1 is considered weak for many applications, making SHA256 the appropriate
    // algorithm for "securely hashing" as requested.
    unsigned char digest[SHA256_DIGEST_LENGTH];

    // Perform the SHA256 hash on the certificate data.
    // cert.c_str() provides a null-terminated C-style string, and cert.length()
    // gives its length without the null terminator, which is correct for hashing the data.
    SHA256(reinterpret_cast<const unsigned char*>(cert.c_str()), cert.length(), digest);

    // Convert the raw byte digest into a hexadecimal string representation.
    // Each byte (8 bits) will be represented by two hexadecimal characters.
    std::stringstream ss;
    ss << std::hex << std::setfill('0'); // Set output to hexadecimal and pad with leading zeros.
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        ss << std::setw(2) << static_cast<int>(digest[i]); // Ensure each byte is formatted as two hex digits.
    }

    return ss.str();
}
